#!/usr/bin/env node
"use strict";

// tools/simulate_revenue_scenarios.js
//
// Simulated customer scenarios for the Strange Works Studio satellite revenue
// lane. Shows the value generated by the first service (Compliance proof
// sprint) and the second service (Compliance template pack) under several
// plausible customer paths.
//
// This script is SIMULATION ONLY. It does not:
//   - touch public-config.js or any review-date or liveMode field,
//   - close any real human-review gate,
//   - generate evidence that should be treated as real,
//   - alter the Operations dashboard hosted-invoice allowlist,
//   - count related-party revenue as market proof.
//
// Every record is flagged simulated: true.

