function round2(n) {
  return Math.round(n * 100) / 100;
}

function serviceForScenario(scenario) {
  const service = SERVICES.find(s => s.key === scenario.serviceKey);
  if (!service) {
    throw new Error(`Unknown serviceKey "${scenario.serviceKey}" in scenario ${scenario.scenarioId}.`);
  }
  return service;
}

function simulateScenario(scenario) {
  const service = serviceForScenario(scenario);
  const gross = service.priceBRL;
  const providerFee = round2(gross * ASSUMED_PROVIDER_FEE.rate + ASSUMED_PROVIDER_FEE.flatBRL);
  const grossAfterRefund = scenario.refund ? round2(gross * 0.5) : gross;
  const netAfterRefund = round2(grossAfterRefund - providerFee);

  const stages = [
    {
      stage: "Draft",
      atDay: 0,
      note: "Order created in private Operations dashboard with non-sensitive scope."
    },
    {
      stage: "Sent",
      atDay: 0,
      note:
        "Hosted invoice link sent from monitored support inbox; URL matches Operations dashboard allowlist."
    },
    {
      stage: "Paid",
      atDay: scenario.paidDays,
      note:
        "Provider or bank settlement confirmed in business account before status change. NFS-e or fiscal receipt issued per accountant route."
    },
    {
      stage: "Delivered",
      atDay: scenario.deliveredDays,
      note:
        "Scoped artifact delivered to access-controlled storage. Acceptance note logged without sensitive data. Receipt chain sealed."
    }
  ];

  if (scenario.refund) {
    stages.push({
      stage: "Refund",
      atDay: scenario.deliveredDays + 2,
      note:
        "Human refund owner approved refund per TERMOS.md. Provider refund recorded; ledger and order updated."
    });
  }

  return {
    simulated: true,
    scenarioId: scenario.scenarioId,
    service: service.name,
    serviceKey: service.key,
    customerLabel: scenario.customerLabel,
    customerType: scenario.customerType,
    grossBRL: round2(gross),
    grossAfterRefundBRL: grossAfterRefund,
    providerFeeBRL: providerFee,
    netBRL: netAfterRefund,
    paidDay: scenario.paidDays,
    deliveredDay: scenario.deliveredDays,
    incidents: scenario.incidents,
    refund: scenario.refund,
    stages,
    notes: scenario.notes
  };
}

function summarize(results) {
  const byService = {};
  for (const result of results) {
    if (!byService[result.service]) {
      byService[result.service] = {
        serviceKey: result.serviceKey,
        scenarioCount: 0,
        grossBRL: 0,
        netBRL: 0,
        refundCount: 0,
        incidentCount: 0
      };
    }
    const bucket = byService[result.service];
    bucket.scenarioCount += 1;
    bucket.grossBRL += result.grossAfterRefundBRL;
    bucket.netBRL += result.netBRL;
    bucket.refundCount += result.refund ? 1 : 0;
    bucket.incidentCount += result.incidents;
  }
  for (const key of Object.keys(byService)) {
    byService[key].grossBRL = round2(byService[key].grossBRL);
    byService[key].netBRL = round2(byService[key].netBRL);
  }
  return byService;
}

function totals(byService) {
  let grossBRL = 0;
  let netBRL = 0;
  let scenarioCount = 0;
  for (const key of Object.keys(byService)) {
    grossBRL += byService[key].grossBRL;
    netBRL += byService[key].netBRL;
    scenarioCount += byService[key].scenarioCount;
  }
  const grossRounded = round2(grossBRL);
  const netRounded = round2(netBRL);
  const marginPct =
    grossRounded > 0 ? round2((netRounded / grossRounded) * 100) : 0;
  return {
    scenarioCount,
    grossBRL: grossRounded,
    netBRL: netRounded,
    marginPct
  };
}

function formatBRL(value) {
  return `R$${value.toFixed(2)}`;
}

function formatReport(results, byService, totalsSummary) {
  const lines = [];
  lines.push("# Revenue Simulation Report");
  lines.push("");
  lines.push(
    "Generated by `tools/simulate_revenue_scenarios.js`. **All data is simulated.** Do not use these IDs, timestamps, or amounts as real evidence. This file is gitignored on purpose."
  );
  lines.push("");
  lines.push("## Assumptions");
  lines.push("");
  lines.push(
    `- Provider fee assumption: ${(ASSUMED_PROVIDER_FEE.rate * 100).toFixed(2)}% + R$${ASSUMED_PROVIDER_FEE.flatBRL.toFixed(2)}.`
  );
  lines.push(`- Notes: ${ASSUMED_PROVIDER_FEE.notes}`);
  lines.push("- Refund scenarios assume a 50% partial refund under TERMOS.md.");
  lines.push("- All customers are simulated external customers. No related-party revenue is counted.");
  lines.push("");
  lines.push("## Per-Service Summary");
  lines.push("");
  lines.push("| Service | Scenarios | Gross | Net | Refunds | Incidents |");
  lines.push("| --- | --- | --- | --- | --- | --- |");
  for (const key of Object.keys(byService)) {
    const bucket = byService[key];
    lines.push(
      `| ${key} | ${bucket.scenarioCount} | ${formatBRL(bucket.grossBRL)} | ${formatBRL(bucket.netBRL)} | ${bucket.refundCount} | ${bucket.incidentCount} |`
    );
  }
  lines.push("");
  lines.push("## Totals");
  lines.push("");
  lines.push(`- Scenarios: ${totalsSummary.scenarioCount}`);
  lines.push(`- Gross: ${formatBRL(totalsSummary.grossBRL)}`);
  lines.push(`- Net: ${formatBRL(totalsSummary.netBRL)}`);
  lines.push(`- Margin: ${totalsSummary.marginPct.toFixed(2)}%`);
  lines.push("");
  lines.push("## Scenario Detail");
  lines.push("");
  for (const result of results) {
    lines.push(`### ${result.scenarioId} - ${result.service}`);
    lines.push("");
    lines.push(`- Customer: ${result.customerLabel} (${result.customerType})`);
    lines.push(
      `- Gross: ${formatBRL(result.grossBRL)} | After refund: ${formatBRL(result.grossAfterRefundBRL)} | Provider fee: ${formatBRL(result.providerFeeBRL)} | Net: ${formatBRL(result.netBRL)}`
    );
    lines.push(
      `- Paid day: T+${result.paidDay} | Delivered day: T+${result.deliveredDay} | Incidents: ${result.incidents} | Refund: ${result.refund ? "yes" : "no"}`
    );
    lines.push(`- Notes: ${result.notes}`);
    lines.push("");
    lines.push("| Stage | Day | Note |");
    lines.push("| --- | --- | --- |");
    for (const stage of result.stages) {
      lines.push(`| ${stage.stage} | T+${stage.atDay} | ${stage.note} |`);
    }
    lines.push("");
  }
  lines.push("## What This Does Not Prove");
  lines.push("");
  lines.push(
    "- This report does not close any human-review gate in `HUMAN_REVENUE_INSTRUCTIONS.md`."
  );
  lines.push(
    "- This report does not authorize setting `liveMode: true` in `public-config.js`."
  );
  lines.push(
    "- These customers are simulated. Real-market traction must come from external customers under the closed gates."
  );
  return lines.join("\n") + "\n";
}

