function printConsoleSummary(byService, totalsSummary) {
  console.log("");
  console.log("=== Revenue Simulation Summary (SIMULATED) ===");
  console.log("");
  for (const key of Object.keys(byService)) {
    const bucket = byService[key];
    console.log(
      `${key}: scenarios=${bucket.scenarioCount} gross=${formatBRL(bucket.grossBRL)} net=${formatBRL(bucket.netBRL)} refunds=${bucket.refundCount} incidents=${bucket.incidentCount}`
    );
  }
  console.log("");
  console.log(
    `Totals: scenarios=${totalsSummary.scenarioCount} gross=${formatBRL(totalsSummary.grossBRL)} net=${formatBRL(totalsSummary.netBRL)} margin=${totalsSummary.marginPct.toFixed(2)}%`
  );
  console.log("");
  console.log("Reminder: this is simulation only. liveMode stays false. No real gate is closed.");
}

function main() {
  const args = process.argv.slice(2);
  const writeReport = args.includes("--write-report");
  const writeEvidence = args.includes("--write-evidence");

  const results = SCENARIOS.map(simulateScenario);
  const byService = summarize(results);
  const totalsSummary = totals(byService);

  if (writeReport) {
    const reportPath = path.join(process.cwd(), "REVENUE_SIMULATION_REPORT.md");
    const reportText = formatReport(results, byService, totalsSummary);
    fs.writeFileSync(reportPath, reportText, "utf8");
    console.log(`Wrote ${path.relative(process.cwd(), reportPath) || reportPath}`);
  }

  if (writeEvidence) {
    const evidencePath = path.join(
      process.cwd(),
      "REVENUE_SETUP_EVIDENCE_INDEX.simulation.json"
    );
    const evidence = buildSimulatedEvidenceIndex(byService, totalsSummary);
    fs.writeFileSync(
      evidencePath,
      JSON.stringify(evidence, null, 2) + "\n",
      "utf8"
    );
    console.log(`Wrote ${path.relative(process.cwd(), evidencePath) || evidencePath}`);
  }

  printConsoleSummary(byService, totalsSummary);
}

if (require.main === module) {
  main();
}

module.exports = {
  SERVICES,
  SCENARIOS,
  ASSUMED_PROVIDER_FEE,
  simulateScenario,
  summarize,
  totals,
  formatReport,
  buildSimulatedEvidenceIndex
};
